import{_ as n,o as t,c as a,a2 as i}from"./chunks/framework.D5wUhsuj.js";const h=JSON.parse('{"title":"PhyAgentOS Framework Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/01-framework-introduction.md","filePath":"en/01-framework-introduction.md"}'),o={name:"en/01-framework-introduction.md"};function s(l,e,r,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="phyagentos-framework-introduction" tabindex="-1">PhyAgentOS Framework Introduction <a class="header-anchor" href="#phyagentos-framework-introduction" aria-label="Permalink to &quot;PhyAgentOS Framework Introduction&quot;">​</a></h1><p><a href="/docs/zh/01-framework-introduction">中文</a> · <a href="/docs/en/">Documentation index</a></p><blockquote><p>Documentation version: 1.0.0 · implementation baseline: 2026-08-30 source, schemas, and tests.</p></blockquote><h2 id="_1-positioning" tabindex="-1">1. Positioning <a class="header-anchor" href="#_1-positioning" aria-label="Permalink to &quot;1. Positioning&quot;">​</a></h2><p>PhyAgentOS is an Agent framework for embodied tasks. The Agent interprets a user goal, selects Forge tools, defines task-level success, and decides whether to continue or recover. Forge Gateway owns Tool execution, ToolEndpoint selection, Dora integration, and robot or simulator access.</p><p>The boundary keeps cognitive planning separate from physical effects. General Agent tools, verification, task experience, evolution, Skill activation, and dynamic MCP tools remain part of the Agent platform; robot execution uses one Forge Query/Action/Session Tool API.</p><h2 id="_2-one-physical-execution-plane" tabindex="-1">2. One physical execution plane <a class="header-anchor" href="#_2-one-physical-execution-plane" aria-label="Permalink to &quot;2. One physical execution plane&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User / Channel / Scheduled Event</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>      AgentLoop + Planner</span></span>
<span class="line"><span>              │  AgentTask-bound call or diagnostic Query</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>       ForgeToolClient ─────────► AgentTask SQLite + evidence</span></span>
<span class="line"><span>              │                         │</span></span>
<span class="line"><span>              │ HTTP Tool API           ▼</span></span>
<span class="line"><span>              ▼                  ForgeTaskVerifier</span></span>
<span class="line"><span> Gateway /tools → ToolInvocation        │</span></span>
<span class="line"><span>              │                  verdict / PlanRevision</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span> ToolEndpoint → Dora → robot/simulator</span></span>
<span class="line"><span></span></span>
<span class="line"><span>terminal AgentTask ─────► Experience Coordinator ──► evolution ledger</span></span></code></pre></div><p>Bound calls and diagnostic Query use the same Gateway endpoints. A diagnostic Query does not occupy the AgentTask slot; Action and task-owned Session require a frozen task binding. PAOS does not add a cross-Tool resource lease; the selected endpoint operation&#39;s <code>max_concurrency</code> decides admission.</p><h2 id="_3-three-kinds-of-fact" tabindex="-1">3. Three kinds of fact <a class="header-anchor" href="#_3-three-kinds-of-fact" aria-label="Permalink to &quot;3. Three kinds of fact&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Fact</th><th style="text-align:left;">Owner</th><th style="text-align:left;">Question</th></tr></thead><tbody><tr><td style="text-align:left;">Execution</td><td style="text-align:left;">Forge Gateway</td><td style="text-align:left;">Which Query completed, or which Action/Session invocation was accepted and how did it terminate?</td></tr><tr><td style="text-align:left;">Evidence</td><td style="text-align:left;">PAOS observation collector</td><td style="text-align:left;">What was observed before and after the task-owned physical executions?</td></tr><tr><td style="text-align:left;">Verdict</td><td style="text-align:left;">PAOS verification</td><td style="text-align:left;">Did the complete set of bound calls satisfy the user goal, criteria, and constraints?</td></tr></tbody></table><p>An Action or Session admission response is not completion. Cancellation/stop acceptance, a local timeout, or an <code>unknown</code> outcome does not prove that physical execution stopped and cannot justify a blind retry.</p><h2 id="_4-identity-model" tabindex="-1">4. Identity model <a class="header-anchor" href="#_4-identity-model" aria-label="Permalink to &quot;4. Identity model&quot;">​</a></h2><p>The following identifiers are intentionally different:</p><ul><li><code>task_id</code>: one user-visible AgentTask aggregate;</li><li><code>binding_id</code>: one immutable Skill/Runtime/ToolSpec snapshot;</li><li><code>revision_id</code>: one immutable planning generation within that task;</li><li>Query/execution <code>record_id</code>: one PAOS record attached to a revision;</li><li><code>caller_id</code>: one PAOS-generated identity persisted before asynchronous admission;</li><li><code>invocation_id</code>: one Gateway-owned asynchronous Action or Session invocation;</li><li><code>attempt_id</code>: one Gateway execution attempt.</li></ul><p>They must not be copied into one another or treated as aliases. Forge remains authoritative for Tool execution facts; AgentTask stores references and task-level interpretation.</p><h2 id="_5-agenttask-lifecycle" tabindex="-1">5. AgentTask lifecycle <a class="header-anchor" href="#_5-agenttask-lifecycle" aria-label="Permalink to &quot;5. AgentTask lifecycle&quot;">​</a></h2><p>Only one AgentTask may be non-terminal globally. A task starts with revision 1 and can contain multiple bound Queries, Actions, and Sessions. PlanRevisions are append-only; prior execution records and verification attempts are never rewritten.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>executing ── finalize success ──► succeeded</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── finalize failure ───────► failed</span></span>
<span class="line"><span>    ├── recovery verdict ───────► awaiting_replan ── begin revision ──► executing</span></span>
<span class="line"><span>    └── cancel request ─────────► cancelling ── reconcile + finalize ─► cancelled/failed</span></span></code></pre></div><p>Task tools create, read, revise, finalize, and cancel this aggregate. Tool API tools read Tool context, invoke Query/Action/Session, reconcile asynchronous status/result, and request cancel/stop.</p><h2 id="_6-verification-and-recovery" tabindex="-1">6. Verification and recovery <a class="header-anchor" href="#_6-verification-and-recovery" aria-label="Permalink to &quot;6. Verification and recovery&quot;">​</a></h2><p>Verification modes are <code>off</code>, <code>audit</code>, <code>enforce</code>, and <code>recovery</code>.</p><ul><li><code>off</code> derives success from bound execution facts and does not call semantic verification.</li><li><code>audit</code> records a verdict while preserving execution-derived terminal semantics.</li><li><code>enforce</code> requires a valid task contract and fails closed on missing evidence, invalid output, service errors, or inconclusive verification.</li><li><code>recovery</code> has the same fail-closed behavior and may return <code>replan_required</code>.</li></ul><p>Recovery appends a bounded PlanRevision to the same <code>task_id</code>. The Planner receives unmet criteria, preserved constraints, guidance, evidence references, and a deadline, then selects Tools again. Unknown Action effects must be reconciled using a persisted invocation ID before another effect is attempted; PAOS never repeats an unknown admission POST.</p><h2 id="_7-evidence" tabindex="-1">7. Evidence <a class="header-anchor" href="#_7-evidence" aria-label="Permalink to &quot;7. Evidence&quot;">​</a></h2><p>PAOS collects configured image sources and optional robot state over Gateway WebSockets. It uses bounded latest-frame buffers, media and size checks, SHA-256, source sequence boundaries, and workspace-relative artifact references. Collection is best-effort: Forge ToolResult and events are the authoritative execution facts.</p><p>Before-capture runs once before the first bound physical execution. Finalization waits for all task-owned executions to be terminal before after-capture and aggregate verification. Query-only tasks can still carry Tool facts but do not fabricate an Action capture window.</p><h2 id="_8-skill-runtime" tabindex="-1">8. Skill Runtime <a class="header-anchor" href="#_8-skill-runtime" aria-label="Permalink to &quot;8. Skill Runtime&quot;">​</a></h2><p>Skill Runtime manages installed manifest-v2 bundles and explicit named Dora profiles. Bundles use safe archive extraction, SHA-256 inventories, exact single-executable node locks, transactional replacement, persistent state, lifecycle logs, and Gateway <code>/tools</code> health checks.</p><p>Skill discovery priority is workspace override, installed Skill, then built-in Skill. A healthy active Runtime makes its Skill available to <code>SkillsLoader</code>, activation, experience, and evolution. The active manifest is the only Gateway URL source.</p><p>Registry downloads require <code>resourceRegistry.url</code>, <code>PAOS_RESOURCE_REGISTRY_URL</code>, or an explicit static index. Downloads happen only after an explicit CLI command and confirmation. Concrete Forge Skills, nodes, models, and simulation assets are not included in the PhyAgentOS distribution.</p><h2 id="_9-experience-and-evolution" tabindex="-1">9. Experience and evolution <a class="header-anchor" href="#_9-experience-and-evolution" aria-label="Permalink to &quot;9. Experience and evolution&quot;">​</a></h2><p>ExperienceCoordinator records all Agent tool calls and associates explicit Skill activations, AgentTask frozen binding/version, PlanRevision verdicts, ToolInvocation references, verification attempts, and evidence references with one redacted task episode.</p><p>Semantic successes can support guarded Skill candidates. Workflow-related semantic failures can form normalized observations and scope-aware Lesson clusters. Infrastructure, evidence, verifier, unsatisfiable-task, and uncertain failures remain diagnostic-only. Evolution is fail-open and cannot change execution or verification results.</p><h2 id="_10-persistence" tabindex="-1">10. Persistence <a class="header-anchor" href="#_10-persistence" aria-label="Permalink to &quot;10. Persistence&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/</span></span>
<span class="line"><span>├── .paos/agent_tasks/tasks.sqlite3</span></span>
<span class="line"><span>├── .paos/evolution/experience.sqlite3</span></span>
<span class="line"><span>├── .paos/evolution/revisions/&lt;skill&gt;/</span></span>
<span class="line"><span>├── skills/&lt;skill&gt;/SKILL.md</span></span>
<span class="line"><span>└── artifacts/agent_tasks/&lt;task_id&gt;/</span></span>
<span class="line"><span>    ├── before_snapshot.json</span></span>
<span class="line"><span>    ├── after_snapshot.json</span></span>
<span class="line"><span>    ├── evidence_bundle.json</span></span>
<span class="line"><span>    └── evidence/</span></span></code></pre></div><p>Runtime installation and lifecycle state live under the configured PAOS data paths, separate from AgentTask and evolution persistence. Existing evolution data is never removed by Runtime cleanup.</p><h2 id="_11-code-map" tabindex="-1">11. Code map <a class="header-anchor" href="#_11-code-map" aria-label="Permalink to &quot;11. Code map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Area</th><th style="text-align:left;">Path</th></tr></thead><tbody><tr><td style="text-align:left;">Agent loop and general tools</td><td style="text-align:left;"><code>PhyAgentOS/agent/</code></td></tr><tr><td style="text-align:left;">Tool API client, binding, and AgentTask</td><td style="text-align:left;"><code>PhyAgentOS/forge/tool_client.py</code>, <code>PhyAgentOS/forge/binding.py</code>, <code>PhyAgentOS/forge/task.py</code></td></tr><tr><td style="text-align:left;">Agent-facing Forge tools</td><td style="text-align:left;"><code>PhyAgentOS/agent/tools/forge_tool_api.py</code>, <code>forge_task.py</code></td></tr><tr><td style="text-align:left;">Skill Runtime</td><td style="text-align:left;"><code>PhyAgentOS/skill_runtime/</code></td></tr><tr><td style="text-align:left;">Built-in Agent workflow Skills</td><td style="text-align:left;"><code>PhyAgentOS/skills/</code></td></tr><tr><td style="text-align:left;">Verification</td><td style="text-align:left;"><code>PhyAgentOS/verification/</code>, <code>PhyAgentOS/agent/session_verifier.py</code></td></tr><tr><td style="text-align:left;">Experience and evolution</td><td style="text-align:left;"><code>PhyAgentOS/agent/experience/</code></td></tr></tbody></table><h2 id="_12-implemented-scope" tabindex="-1">12. Implemented scope <a class="header-anchor" href="#_12-implemented-scope" aria-label="Permalink to &quot;12. Implemented scope&quot;">​</a></h2><p>The current runtime supports Query, Action, and Session through the unified Tool API. Cross-Tool resource leases, implicit Registry downloads, and bundled concrete robot/simulator artifacts are outside the implemented contract.</p><h2 id="next-reading" tabindex="-1">Next reading <a class="header-anchor" href="#next-reading" aria-label="Permalink to &quot;Next reading&quot;">​</a></h2><ul><li><a href="/docs/en/02-user-manual">User Manual</a></li><li><a href="/docs/en/03-developer-manual">Developer Manual</a></li><li><a href="/docs/forge/README">Forge Tool API Integration Contract</a></li><li><a href="/docs/en/05-agent-experience-and-skill-evolution">Agent Experience and Skill Evolution</a></li></ul>`,43)])])}const f=n(o,[["render",s]]);export{h as __pageData,f as default};
